      if (!rect || !usableRect(rect)) return;
      // 区域标记的是"这块地方",不是里面的元素:把它展开成选择集会让结果
      // 依赖页面 markup,而不是你框住的那块画面。
      regions.push({ id: nextId('region'), rect: rect });
      var outline = document.createElementNS(svgNS, 'rect');
